import{_ as a,q as n,s as e,J as t}from"./framework-4ff91fa4.js";const s={},r=t(`<h2 id="android-路线" tabindex="-1"><a class="header-anchor" href="#android-路线" aria-hidden="true">#</a> Android 路线</h2><p>先掌握类、空安全、集合和协程，再学习 Android Studio、Jetpack Compose、状态管理、生命周期和数据持久化。Compose 的重组与状态系统属于框架知识，不是 Kotlin 基础语法。重点练习配置变化、恢复状态和取消页面任务。</p><h2 id="jvm-后端路线" tabindex="-1"><a class="header-anchor" href="#jvm-后端路线" aria-hidden="true">#</a> JVM 后端路线</h2><p>在 Kotlin/JVM 基础上学习 HTTP、数据库、事务、认证与部署，再选择 Ktor 或 Spring 等框架。把挂起 API 与阻塞数据库访问的线程策略安排清楚；不要将 suspend 当成数据库自动异步化开关。</p><h2 id="kotlin-multiplatform" tabindex="-1"><a class="header-anchor" href="#kotlin-multiplatform" aria-hidden="true">#</a> Kotlin Multiplatform</h2><p>共享业务逻辑通常放在 commonMain，平台实现放在 jvmMain、iosMain 等源集。通用代码不能直接使用 java.io 等 JVM 专属 API。expect / actual 用于描述平台边界，例如：</p><div class="language-kotlin line-numbers-mode" data-ext="kt"><pre class="language-kotlin"><code><span class="token comment">// commonMain：声明所需能力</span>
<span class="token keyword">expect</span> <span class="token keyword">fun</span> <span class="token function">platformName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> String
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-kotlin line-numbers-mode" data-ext="kt"><pre class="language-kotlin"><code><span class="token comment">// jvmMain：提供 JVM 实现</span>
<span class="token keyword">actual</span> <span class="token keyword">fun</span> <span class="token function">platformName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> String <span class="token operator">=</span> <span class="token string-literal singleline"><span class="token string">&quot;JVM&quot;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>这是不同源集中的配置片段，需要先创建支持多平台的 Gradle 项目，不能把两个声明直接塞进普通 JVM 文件。优先共享稳定业务逻辑，不强求所有平台实现完全一致。</p><h2 id="作品与复习计划" tabindex="-1"><a class="header-anchor" href="#作品与复习计划" aria-hidden="true">#</a> 作品与复习计划</h2><p>第一轮完成学习清单；第二轮补测试与 JSON 文件；第三轮选择一个平台，做真正可用的小工具。每轮记录一个设计选择和一个失败案例，形成自己的博客文章。</p><p>官方资源：<a href="https://kotlinlang.org/docs/home.html" target="_blank" rel="noopener noreferrer">Kotlin 文档</a>、<a href="https://developer.android.com/kotlin" target="_blank" rel="noopener noreferrer">Android Kotlin</a>、<a href="https://kotlinlang.org/docs/multiplatform/get-started.html" target="_blank" rel="noopener noreferrer">多平台起步</a>。先跑通官方最小样例，再加入自己的需求。</p><h2 id="动手练习" tabindex="-1"><a class="header-anchor" href="#动手练习" aria-hidden="true">#</a> 动手练习</h2><p>选择一条路线，为学习清单设计三个下一阶段功能。</p><details><summary>查看参考思路</summary><p>例如 Android：本地持久化、筛选完成状态、生命周期安全的异步加载；每项都应有明确验收条件。</p></details><h2 id="延伸阅读" tabindex="-1"><a class="header-anchor" href="#延伸阅读" aria-hidden="true">#</a> 延伸阅读</h2><p><a href="https://kotlinlang.org/docs/multiplatform.html" target="_blank" rel="noopener noreferrer">Kotlin 官方文档：multiplatform</a>。本章为原创中文学习笔记，示例以 Kotlin/JVM 为主；使用扩展库的章节需先配置依赖。</p>`,17),o=[r];function i(l,d){return n(),e("div",null,o)}const c=a(s,[["render",i],["__file","next-steps.html.vue"]]);export{c as default};
